{
  "sections": [
    {
      "key": "card_identity_metadata",
      "title": "Card Identity Metadata",
      "body": "- Product: Weekly family dinner planner\n- Scope: 7-day dinner plan\n- Inputs: budget, family size, dietary constraints\n- Outputs: per-day meal, ingredients, estimated cost, consolidated shopping list\n- Source basis: worksheet, cheatSheet, execSummary, implementation"
    },
    {
      "key": "executive_summary",
      "title": "Executive Summary",
      "body": "Deliver a 7-day dinner plan for a family of four within a $120 budget. Include a consolidated shopping list. Enforce total estimated meal cost at or below budget."
    },
    {
      "key": "dna_architecture",
      "title": "DNA Architecture",
      "body": "- Core function: generate weekly dinner plans\n- Planning horizon: 7 days\n- Target household: family of four\n- Budget cap: 120\n- Meal constraint: dinners only\n- Time constraint: 30 minutes or less active cooking per dinner\n- Dietary constraints: apply from input"
    },
    {
      "key": "orchestration_layer",
      "title": "Orchestration Layer",
      "body": "- Ingest inputs: budget, family size, dietary constraints\n- Generate structured meal plan with LLM\n- Format output to deterministic JSON schema\n- Validate total estimated cost against budget\n- Return meal plan and shopping list"
    },
    {
      "key": "n_layer_detection_engine",
      "title": "N-Layer Detection Engine",
      "body": "- Validation rule: sum of daily meal costs must be less than or equal to budget\n- Schema rule: output must match days[] and shoppingList[]\n- Constraint checks: 7 dinners required; active cook time per dinner must be 30 minutes or less; dietary constraints must be respected"
    },
    {
      "key": "context_craft_pillars",
      "title": "Context Craft Pillars",
      "body": "- Budget discipline\n- Family-size fit\n- Dietary compliance\n- Fast preparation\n- Consolidated grocery planning"
    },
    {
      "key": "hive_matrix_certification",
      "title": "Hive Matrix Certification",
      "body": "Source PDD does not specify; defer to source."
    },
    {
      "key": "workflow_examples",
      "title": "Workflow Examples",
      "body": "- Input: budget=120, familySize=4, dietaryConstraints=[]\n- Output: 7 dinner entries with meal name, ingredients, estimated cost, and one consolidated shopping list"
    },
    {
      "key": "integration_protocols",
      "title": "Integration Protocols",
      "body": "- Generation engine: LLM\n- Output contract: deterministic JSON\n- Required arrays: days[], shoppingList[]"
    },
    {
      "key": "evolution_roadmap",
      "title": "Evolution Roadmap",
      "body": "Source PDD does not specify; defer to source."
    },
    {
      "key": "business_impact",
      "title": "Business Impact",
      "body": "- Produces a budget-bounded weekly dinner plan\n- Reduces meal-planning effort\n- Simplifies grocery shopping through consolidation"
    },
    {
      "key": "risk_register",
      "title": "Risk Register",
      "body": "- Risk: generated plan exceeds budget\n  - Mitigation: validate sum(costs) against budget\n- Risk: output schema drift\n  - Mitigation: deterministic JSON schema validation\n- Risk: dietary mismatch\n  - Mitigation: pass and check dietary constraints"
    },
    {
      "key": "governance_signing",
      "title": "Governance Signing",
      "body": "- Acceptance criteria:\n  - 7 dinners generated\n  - Family size supported\n  - Total estimated cost is less than or equal to budget\n  - Shopping list is consolidated\n  - Active cook time per dinner is 30 minutes or less"
    },
    {
      "key": "lineage_traceability",
      "title": "Lineage Traceability",
      "body": "- worksheet -> inputs and outputs\n- cheatSheet -> weekly planner, 7 dinners, shopping list, 30-minute cook limit\n- execSummary -> family of four, 120 budget, consolidated shopping list\n- implementation -> LLM generation, deterministic JSON schema, budget validation"
    },
    {
      "key": "spc_signature",
      "title": "SPC Signature",
      "body": "- SPARTAN SCM compression applied\n- Preserved load-bearing constraints: 7 days, family of four, 120 budget, consolidated shopping list, deterministic JSON, budget validation\n- Certification status recorded below"
    }
  ],
